    const holdChosenSeats = async (): Promise<boolean> => {
        const claims = flights.flatMap((flight, legIndex) =>
            passengers
                .map(passenger => passenger.seatNumbers[legIndex])
                .filter((seat): seat is string => Boolean(seat))
                .map(seatNumber => ({ flightId: flight.id, seatNumber })),
        );
        if (claims.length === 0) return true;

        let result;
        try {
            idempotencyKeyRef.current ??= createBookingRequestId();
            result = await holdChosenSeatsAction({
                checkoutId: idempotencyKeyRef.current,
                claims,
            });
        } catch {
            // An expired session or a dropped connection. Without this the
            // promise rejects into nothing: no message, and a button that
            // simply stops working.
            errorClaimsFocus.current = true;
            setErrorMessage('We could not hold those seats just now. Please try again.');
            return false;
        }

        if (result.ok) return true;

        if ('takenSeats' in result) {
            const taken = result.takenSeats;
            // Which leg, not just which seat. A round trip can carry 16A on
            // both, and matching by number alone marked whichever leg the
            // customer happened to be looking at -- telling them a seat they
            // had just been granted was gone.
            const lostByLeg = flights.map(flight =>
                taken.filter(seat => seat.flightId === flight.id).map(seat => seat.seatNumber));

            setOccupiedSeatsByLeg(previous => previous.map((seats, legIndex) => [
                ...new Set([...seats, ...(lostByLeg[legIndex] ?? [])]),
            ]));

            // Let the seat go. Left in place it reads as chosen in the
            // passenger list while the map draws it occupied and disabled, and
            // `validateStep2` keeps passing, so pressing the button again just
            // re-fails against a seat that can never be had.
            setPassengers(previous => previous.map(passenger => ({
                ...passenger,
                seatNumbers: passenger.seatNumbers.map((seat, legIndex) =>
                    seat && lostByLeg[legIndex]?.includes(seat) ? '' : seat),
            })));

            const firstLostLeg = lostByLeg.findIndex(seats => seats.length > 0);
            if (firstLostLeg >= 0) setActiveLegIndex(firstLostLeg);

            const names = taken.map(seat => flights.length > 1
                ? `${seat.seatNumber} on the ${legDirectionLabel(
                    flights.findIndex(flight => flight.id === seat.flightId), flights.length,
                ).toLowerCase()} flight`
                : seat.seatNumber);
            // "Being held" rather than "taken": the other customer may yet
            // abandon their checkout, and claiming a sale that has not happened
            // is a claim that is often untrue.
            errorClaimsFocus.current = true;
            setErrorMessage(
                names.length === 1
                    ? `Seat ${names[0]} is being held by another customer while they check out. Please choose a different one.`
                    : `Seats ${names.join(' and ')} are being held by other customers while they check out. Please choose different ones.`,
            );
            return false;
        }

        errorClaimsFocus.current = true;
        setErrorMessage(result.error?.message ?? 'Those seats could not be held. Please try again.');
        return false;
    };

    const errorRef = useRef<HTMLDivElement | null>(null);
    /**
     * Whether this error is the banner's to own.
     *
     * Server validation errors route focus to the field they name, which is

    return [...new Set([...assignments.map(seat => seat.seatNumber), ...beingChosen])];
}

/**
 * Claim every seat the customer has chosen, for as long as it takes to pay.
 *
 * Called when they leave the seat map, not on each click. A hold per click
 * would have to follow every swap and deselection around the wizard, and the
 * window that actually matters is the one between choosing and paying.
 *
 * Reports which seats went rather than which succeeded: a customer who cannot
 * continue needs to know what to change, and "seat 12A has just been taken" is
 * the whole message. Seats claimed before the refusal stay claimed -- they are
 * the customer's, they expire on their own, and releasing them would hand away
 * seats over a problem with a different one.
 */
export async function holdChosenSeatsAction(request: {
    checkoutId: string;
    claims: { flightId: number; seatNumber: string }[];
}) {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) throw new Error("Unauthorized");

    const parsed = parseActionInput(checkoutSeatClaimsSchema, request);
    if (!parsed.ok) return parsed;

    const { checkoutId, claims: wanted } = parsed.data;
    const holderKey = checkoutHolderKey(session.user.id, checkoutId);

    // A customer who went back and changed their mind would otherwise strand
    // the seat they abandoned for the rest of its ten minutes.
    await releaseHoldsExcept([...new Set(wanted.map(claim => claim.flightId))], holderKey, wanted);

    const taken: { flightId: number; seatNumber: string }[] = [];
    for (const claim of wanted) {
        const held = await holdSeat({ ...claim, holderKey });
        if (!held) taken.push(claim);
    }

    // The leg travels with the seat. A round trip can carry 16A twice, and
    // reporting the number alone made the caller mark whichever leg it found
    // first -- so a customer who *had* been granted their outbound seat was
    // told it was gone while the leg that actually failed sat on another tab.
    return taken.length > 0 ? { ok: false as const, takenSeats: taken } : { ok: true as const };
}

export async function toggleFavoriteCityGuideAction(cityGuideId: number) {
    const session = await getServerSession(authOptions);

/**
 * Give up a claim.
 *
 * Scoped to the holder on purpose: releasing by seat alone would let one
 * customer hand another's seat away, and the caller is whatever the browser
 * sent. A release that matches nothing is silent -- the seat is not yours and
 * the outcome you asked for, that you are not holding it, is already true.
 */
export async function releaseHold({ flightId, seatNumber, holderKey }: SeatClaim): Promise<void> {
    await prisma.seatHold.deleteMany({ where: { flightId, seatNumber, holderKey } });
}

/**
 * The seats on this flight that somebody *else* is currently holding.
 *
 * Excludes your own, or the seat a customer just picked would grey out under
 * them. Sorted so a caller can compare the list without minding the order the
 * rows came back in.
 */
async function liveHolds(flightId: number): Promise<{ seatNumber: string; holderKey: string }[]> {
    return prisma.$queryRaw<{ seatNumber: string; holderKey: string }[]>`
        SELECT "seatNumber", "holderKey" FROM "SeatHold"
        WHERE "flightId" = ${flightId}
          AND "expiresAt" > now()
        ORDER BY "seatNumber"
    `;
}

export async function seatsHeldByOthers(flightId: number, holderKey: string): Promise<string[]> {
    const held = await liveHolds(flightId);
    return held.filter(row => row.holderKey !== holderKey).map(row => row.seatNumber);
}

