import type { Prisma } from '@prisma/client';

type FlightLockClient = Pick<Prisma.TransactionClient, '$queryRaw'>;

export async function lockFlightForUpdate(tx: FlightLockClient, flightId: number): Promise<void> {
    await tx.$queryRaw`SELECT "id" FROM "Flight" WHERE "id" = ${flightId} FOR UPDATE`;
}

/**
 * Locks the bookings touching a flight, so two staff transactions changing two
 * legs of one itinerary cannot both decide its status from a stale snapshot.
 *
 * Locking the flight is not enough. `updateFlightStatusAction` decides each
 * booking's new status by reading the statuses of *other* flights -- the other
 * legs -- and those rows belong to flights this transaction does not hold. Under
 * READ COMMITTED two concurrent changes each read the other's pre-image, and
 * both are wrong: cancelling one leg while reinstating another left the booking
 * CONFIRMED on a cancelled flight, and reinstating both at once left it
 * DISRUPTED while both flights operated (#76).
 *
 * The booking row is what they have in common, so it is what serialises them.
 * Ascending id, matching every other lock order in this application, so two
 * transactions holding overlapping sets cannot form a cycle. Once the second
 * transaction is through the lock its next statement takes a fresh snapshot and
 * sees the first one's committed work.
 */
export async function lockBookingsOnFlightForUpdate(
    tx: FlightLockClient,
    flightId: number,
): Promise<number[]> {
    const locked = await tx.$queryRaw<Array<{ id: number }>>`
        SELECT b."id"
        FROM "Booking" b
        WHERE EXISTS (
            SELECT 1 FROM "ItineraryLeg" l
            WHERE l."bookingId" = b."id" AND l."flightId" = ${flightId}
        )
        AND b."status" <> 'CANCELLED'
        ORDER BY b."id"
        FOR UPDATE
    `;
    return locked.map(row => row.id);
}
/**
 * When a seat counts as taken.
 *
 * One rule — a seat is held unless the booking holding it was cancelled — asked
 * by four queries: booking a flight, reading a seat map, changing a seat, and
 * editing a cabin layout. Each wrote the condition out again, so getting it
 * wrong in one place meant a seat that was free on one screen and taken on
 * another.
 *
 * It is stated here because three queued issues rewrite those same call sites
 * independently — inventory holds (#74), payments (#75) and cancellation rules
 * (#76) — and each would otherwise have to find all four and change them the
 * same way (#143).
 *
 * Note what this is *not*: `searchFlightsAction` filters cancelled **flights**
 * out of search results, which reads similarly and is a different question. A
 * cancelled flight is not a released seat.
 */

const HELD_SEAT = {
    releasedAt: null,
} as const;

/**
 * Narrows a seat-assignment query to the seats that are actually held.
 *
 *     where: heldSeats({ flightId })
 *     where: heldSeats({ flightId: { in: ids }, NOT: { leg: { bookingId } } })
 *     where: heldSeats()
 *
 * A function rather than an object to spread, because the rule has to win.
 * Spread beside a caller's conditions it could be erased by one of them: a
 * `releasedAt` key written *before* the spread is a TypeScript error, but the
 * same key written *after* it compiles cleanly and drops the condition from the
 * SQL entirely — no released seats filtered, and nothing to grep for. Applying
 * the rule last means a caller cannot lose it by accident, only by editing this
 * file.
 *
