/** @jest-environment node */
import { airportCodesForRoute } from '@/lib/airports';
import { getOccupiedSeatsAction, holdChosenSeatsAction } from '@/app/actions';
import { randomUUID } from 'crypto';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import FlightBookingService from '@/lib/FlightBookingService';
import { holdSeat } from '@/lib/seatHolds';

jest.mock('next-auth', () => ({ getServerSession: jest.fn() }));
jest.mock('next/cache', () => ({ revalidatePath: jest.fn() }));
jest.mock('@/lib/auth', () => ({ authOptions: {} }));

const mockedGetServerSession = getServerSession as unknown as jest.Mock;

beforeEach(() => {
    // The action refuses an unauthenticated caller (#154). These cases are
    // about which seats come back, not about who is asking, so they run as a
    // signed-in traveller; the refusal itself is covered in actions.test.ts.
    mockedGetServerSession.mockResolvedValue({ user: { id: 'occupied-seats-suite' } });
});

const created = {
    flightIds: [] as number[],
    bookingIds: [] as number[],
    userIds: [] as string[],
    holderKeys: [] as string[],
};

async function createFlight(suffix: string, from: string, to: string, day: string) {
    const flight = await prisma.flight.create({
        data: {
            flightNumber: `OCC-${suffix}`,
            airline: 'Gemini Airways',
            ...airportCodesForRoute(from, to),
            departureDate: new Date(`${day}T08:00:00Z`),
            priceCents: 35000,
            status: 'ON_TIME',
            economyRows: 20,
            premiumEconomyRows: 4,
            businessRows: 3,
            firstClassRows: 3,
            seatPattern: 'ABC-DEF',
        },
    });
    created.flightIds.push(flight.id);
    return flight;
}

afterAll(async () => {
    await prisma.seatHold.deleteMany({
        where: {
            OR: [
                { holderKey: { in: created.holderKeys } },
                { flightId: { in: created.flightIds } },
            ],
        },
    });
    for (const bookingId of created.bookingIds) {
        await prisma.passenger.deleteMany({ where: { bookingId } });
        await prisma.booking.deleteMany({ where: { id: bookingId } });
    }
    await prisma.flight.deleteMany({ where: { id: { in: created.flightIds } } });
    await prisma.user.deleteMany({ where: { id: { in: created.userIds } } });
    await prisma.$disconnect();
});

describe('getOccupiedSeatsAction across an itinerary', () => {
    it('reports the seats taken on the flight asked about, not the outbound seat', async () => {
        const suffix = `${Date.now()}`;
        const outbound = await createFlight(`O${suffix}`, 'Seattle, USA', 'Detroit, USA', '2027-09-01');
        const inbound = await createFlight(`I${suffix}`, 'Detroit, USA', 'Seattle, USA', '2027-09-08');
        const user = await prisma.user.create({
            data: {
                name: 'Occupancy',
                email: `occupancy-${suffix}@example.com`,
                password: 'not-used',
                emailVerified: new Date(),
            },
        });
        created.userIds.push(user.id);

        const booking = await new FlightBookingService().bookFlight({
            flightIds: [outbound.id, inbound.id],
            userId: user.id,
            passengers: [{
                firstName: 'Ada',
                lastName: 'Lovelace',
                dateOfBirth: new Date('1990-01-01'),
                passportNumber: 'US1112223',
                gender: 'Female',
                // Deliberately different per leg, so reading the wrong table
                // cannot accidentally give the right answer.
                seatNumbers: ['11A', '17F'],
                cabinClass: 'ECONOMY',
            }],
            idempotencyKey: randomUUID(),
        });
        created.bookingIds.push(booking.id);

        expect(await getOccupiedSeatsAction(outbound.id)).toEqual(['11A']);
        // The return leg holds 17F. Reading Passenger.seatNumber would answer
        // 11A here, marking a free seat taken and the taken one free.
        expect(await getOccupiedSeatsAction(inbound.id)).toEqual(['17F']);
    });

    it('reports nothing once the booking is cancelled', async () => {
        const suffix = `${Date.now()}c`;
        const flight = await createFlight(`C${suffix}`, 'Seattle, USA', 'Detroit, USA', '2027-10-01');
        const user = await prisma.user.create({
            data: {
                name: 'Occupancy Cancel',
                email: `occupancy-cancel-${suffix}@example.com`,
                password: 'not-used',
                emailVerified: new Date(),
            },
        });
        created.userIds.push(user.id);

        const booking = await new FlightBookingService().bookFlight({
            flightIds: [flight.id],
            userId: user.id,
            passengers: [{
                firstName: 'Grace',
                lastName: 'Hopper',
                dateOfBirth: new Date('1985-05-05'),
                passportNumber: 'US4445556',
                gender: 'Female',
                seatNumbers: ['12B'],
                cabinClass: 'ECONOMY',
            }],
            idempotencyKey: randomUUID(),
        });
        created.bookingIds.push(booking.id);

        expect(await getOccupiedSeatsAction(flight.id)).toEqual(['12B']);

        await prisma.booking.update({ where: { id: booking.id }, data: { status: 'CANCELLED' } });
        expect(await getOccupiedSeatsAction(flight.id)).toEqual([]);
    });
});

describe('a seat another customer is choosing', () => {
    it('keeps two checkouts belonging to the same customer independent', async () => {
        const flight = await createFlight(
            randomUUID().slice(0, 6),
            'Seattle, USA',
            'Detroit, USA',
            '2026-09-01',
        );
        const [firstCheckout, secondCheckout] = [randomUUID(), randomUUID()];

        await expect(holdChosenSeatsAction({
            checkoutId: firstCheckout,
            claims: [{ flightId: flight.id, seatNumber: '12A' }],
        })).resolves.toEqual({ ok: true });
        await expect(holdChosenSeatsAction({
            checkoutId: secondCheckout,
            claims: [{ flightId: flight.id, seatNumber: '12B' }],
        })).resolves.toEqual({ ok: true });

        let rows = await prisma.seatHold.findMany({
            where: { flightId: flight.id },
            orderBy: { seatNumber: 'asc' },
        });
        expect(rows.map(row => row.seatNumber)).toEqual(['12A', '12B']);
        expect(new Set(rows.map(row => row.holderKey))).toHaveProperty('size', 2);

        // Updating the second checkout releases only its abandoned seat. The
        // first tab's 12A remains held even though both tabs share one session.
        await expect(holdChosenSeatsAction({
            checkoutId: secondCheckout,
            claims: [{ flightId: flight.id, seatNumber: '12C' }],
        })).resolves.toEqual({ ok: true });

        rows = await prisma.seatHold.findMany({
            where: { flightId: flight.id },
            orderBy: { seatNumber: 'asc' },
        });
        expect(rows.map(row => row.seatNumber)).toEqual(['12A', '12C']);
    });

    it('counts every live hold when the caller has no checkout identity', async () => {
        // The read half of #74. Without it the hold decides races invisibly:
        // both customers still see the seat as free, and the loser only finds
        // out when advancing to payment fails.
        const flight = await createFlight(randomUUID().slice(0, 6), 'Seattle, USA', 'Detroit, USA', '2026-09-01');
        const rival = `rival-${randomUUID()}`;
        created.holderKeys.push(rival, 'occupied-seats-suite');

    // Both halves matter, and only a rendered page can check them together.
    // Releasing a seat now keeps the real number on the row, so the page must
    // load `releasedAt` *and* render from it -- drop either and this prints
    // 11B, a seat the customer no longer holds and somebody else may (#76).
    await expect(page.locator('text=Bob (Seat released)')).toBeVisible();
    await expect(page.locator('text=Bob (Seat 11B)')).not.toBeVisible();

    // Confirm points are deducted back to starting points (1300)
    const pointsTextAfterCancel = await page.locator('p:has-text("Status Points")').textContent();
    const pointsNumAfter = parseInt(pointsTextAfterCancel?.replace(/[^0-9]/g, '') || '0', 10);
    expect(pointsNumAfter).toBe(1300);

    // Confirm negative entry is visible in points activity log
    await expect(page.locator('text=❌ Cancelled:').first()).toBeVisible();
  });

  test('legacy /book/:id links redirect to the itinerary checkout', async ({ page }) => {
    const flight = await prisma.flight.findFirstOrThrow({
      where: { departureDate: { gt: new Date() } },
      orderBy: { departureDate: 'asc' }
    });

    await page.goto(`/book/${flight.id}`);

    await expect(page).toHaveURL(`/checkout?outbound=${flight.id}`);
    await expect(page.locator('h2:has-text("Traveler Information")')).toBeVisible();
  });

  test('two checkout tabs keep independent seat holds for the same account', async ({ page, context }) => {
    const flight = await prisma.flight.findFirstOrThrow({
      where: { departureDate: { gt: new Date() } },
      orderBy: { departureDate: 'asc' }
    });
    const secondTab = await context.newPage();
    const checkoutUrl = `/checkout?outbound=${flight.id}`;

    await Promise.all([page.goto(checkoutUrl), secondTab.goto(checkoutUrl)]);

    const reachSeats = async (checkout: typeof page, passport: string) => {
      await checkout.fill('input[placeholder="John"]', 'Tab');
      await checkout.fill('input[placeholder="Doe"]', 'Traveler');
      await checkout.fill('input[type="date"]', '1990-05-15');
      await checkout.fill('input[placeholder="A00000000"]', passport);
      await checkout.getByRole('button', { name: 'Select Seats →' }).click();
    };
    await Promise.all([
      reachSeats(page, 'US-TAB-A'),
      reachSeats(secondTab, 'US-TAB-B'),
    ]);

    const firstSeat = page.locator('button[title^="Select Seat"]').first();
    const secondSeat = secondTab.locator('button[title^="Select Seat"]').nth(1);
    const firstSeatName = (await firstSeat.getAttribute('title'))!.replace('Select Seat ', '');
    const secondSeatName = (await secondSeat.getAttribute('title'))!.replace('Select Seat ', '');
    expect(firstSeatName).not.toBe(secondSeatName);

    await firstSeat.click();
    await page.getByRole('button', { name: 'Review Booking →' }).click();
    await expect(page.getByRole('heading', { name: 'Review Booking' })).toBeVisible();

    await secondSeat.click();
    await secondTab.getByRole('button', { name: 'Review Booking →' }).click();
    await expect(secondTab.getByRole('heading', { name: 'Review Booking' })).toBeVisible();

    const heldByBothTabs = await prisma.seatHold.findMany({
      where: {
        flightId: flight.id,
        seatNumber: { in: [firstSeatName, secondSeatName] },
      },
      orderBy: { seatNumber: 'asc' },
    });
    expect(heldByBothTabs.map(hold => hold.seatNumber).sort()).toEqual(
      [firstSeatName, secondSeatName].sort(),
    );
    expect(new Set(heldByBothTabs.map(hold => hold.holderKey))).toHaveProperty('size', 2);

    // Completing one checkout cleans up only its claim. The other tab remains
    // on review with the seat it is still deciding whether to buy.
    await page.locator('button:has-text("Confirm $")').click();
    await expect(page.getByRole('heading', { name: 'Booking Confirmed!' })).toBeVisible();
    await expect(prisma.seatHold.findMany({
      where: {
        flightId: flight.id,
        seatNumber: { in: [firstSeatName, secondSeatName] },
      },
    })).resolves.toMatchObject([{ seatNumber: secondSeatName }]);

    await secondTab.close();
  });

  test('User chooses both legs in search and carries them into checkout', async ({ page }) => {
    await page.goto('/');
    await expect(page.locator('[data-search-ready="true"]')).toBeVisible();

    // The default route operates in both directions (#113), so a round-trip
    // search returns real return inventory to choose from.
    await page.getByRole('button', { name: 'Find your trip' }).click();
    const inbound = page.getByTestId('inbound-results');
    await expect(inbound).toBeVisible();
    await expect(inbound.locator('.flight-result-card').first()).toBeVisible();

    // A round trip is not bookable one card at a time.
    await expect(page.getByRole('link', { name: 'Book Now' })).toHaveCount(0);

    const cta = page.getByTestId('round-trip-book');
    await expect(cta).toHaveAttribute('aria-disabled', 'true');
    await expect(page.getByTestId('round-trip-summary')).toContainText(/choose a departing flight/i);

    await page.getByRole('button', { name: /as the departing leg/ }).first().click();
    await expect(page.getByTestId('round-trip-summary')).toContainText(/choose a return flight/i);

    await page.getByRole('button', { name: /as the return leg/ }).first().click();
    await expect(page.getByTestId('round-trip-summary')).toContainText(/total/i);

    const href = await page.getByTestId('round-trip-book').getAttribute('href');
    expect(href).toMatch(/^\/checkout\?outbound=\d+&inbound=\d+$/);

    await page.getByTestId('round-trip-book').click();

    // Checkout receives both legs, so the wizard offers a seat for each.
    await expect(page).toHaveURL(href!);

