    ]);
}

async function orderedWithFlightLock(flightId) {
    const run = (client, holderKey, orderedSeats) => client.$transaction(
        async (tx) => {
            await tx.$queryRaw`
                SELECT "id"
                FROM "Flight"
                WHERE "id" = ${flightId}
                FOR UPDATE
            `;
            const results = [];
            for (const seatNumber of [...orderedSeats].sort()) {
                results.push(await claimSeat(tx, flightId, seatNumber, holderKey));
            }
            return results;
        },
        { maxWait: 5_000, timeout: 15_000 },
    );

    return Promise.allSettled([
        run(firstClient, `${runId}-safe-one`, seats),
        run(secondClient, `${runId}-safe-two`, [...seats].reverse()),
    ]);
}

function summarize(outcomes) {
    return outcomes.map((outcome) => outcome.status === 'fulfilled'
        ? { status: outcome.status, claims: outcome.value }
        : {
            status: outcome.status,
            code: outcome.reason?.code ?? outcome.reason?.meta?.code ?? 'unknown',
            message: String(outcome.reason?.message ?? outcome.reason).split('\n').at(-1),
        });
}

try {
    const [flight] = await firstClient.$queryRaw`
        SELECT "id"
        FROM "Flight"
        ORDER BY "id"
        LIMIT 1
    `;
    if (!flight) {
        throw new Error('Prototype needs one existing Flight row.');
    }

    const flightId = Number(flight.id);
    await clear(flightId);
    const unsafe = await unsafeOppositeOrder(flightId);
    await clear(flightId);
    const safe = await orderedWithFlightLock(flightId);

    console.log(JSON.stringify({
        flightId,
        unsafe: summarize(unsafe),
        orderedWithFlightLock: summarize(safe),
    }, null, 2));
} finally {
    const [flight] = await firstClient.$queryRaw`
        SELECT "id"
        FROM "Flight"
        ORDER BY "id"
        LIMIT 1
    `;
    if (flight) {
        await clear(Number(flight.id));
    }
    await Promise.all([firstClient.$disconnect(), secondClient.$disconnect()]);
}

