        await holdSeat({ flightId: flight.id, seatNumber: '10A', holderKey: theirs });
        await releaseHold({ flightId: flight.id, seatNumber: '10A', holderKey: mine });

        expect(await seatsHeldByOthers(flight.id, mine)).toEqual(['10A']);
    });
