import type { Prisma } from '@prisma/client';

type FlightLockClient = Pick<Prisma.TransactionClient, '$queryRaw'>;

export async function lockFlightForUpdate(tx: FlightLockClient, flightId: number): Promise<void> {
    await tx.$queryRaw`SELECT "id" FROM "Flight" WHERE "id" = ${flightId} FOR UPDATE`;
}

/**
 * Locks the bookings touching a flight, so two staff transactions changing two
 * legs of one itinerary cannot both decide its status from a stale snapshot.
 *
 * Locking the flight is not enough. `updateFlightStatusAction` decides each
 * booking's new status by reading the statuses of *other* flights -- the other
 * legs -- and those rows belong to flights this transaction does not hold. Under
 * READ COMMITTED two concurrent changes each read the other's pre-image, and
 * both are wrong: cancelling one leg while reinstating another left the booking
 * CONFIRMED on a cancelled flight, and reinstating both at once left it
 * DISRUPTED while both flights operated (#76).
 *
 * The booking row is what they have in common, so it is what serialises them.
 * Ascending id, matching every other lock order in this application, so two
 * transactions holding overlapping sets cannot form a cycle. Once the second
 * transaction is through the lock its next statement takes a fresh snapshot and
 * sees the first one's committed work.
 */
export async function lockBookingsOnFlightForUpdate(
    tx: FlightLockClient,
    flightId: number,
): Promise<number[]> {
    const locked = await tx.$queryRaw<Array<{ id: number }>>`
        SELECT b."id"
        FROM "Booking" b
        WHERE EXISTS (
            SELECT 1 FROM "ItineraryLeg" l
            WHERE l."bookingId" = b."id" AND l."flightId" = ${flightId}
        )
        AND b."status" <> 'CANCELLED'
        ORDER BY b."id"
        FOR UPDATE
    `;
    return locked.map(row => row.id);
}
const nextJest = require('next/jest')

const createJestConfig = nextJest({
  // Provide the path to your Next.js app to load next.config.js and .env files in your test environment
  dir: './',
})

// Add any custom config to be passed to Jest. Shared by both projects below;
// only the file selection differs.
const customJestConfig = {
  setupFilesAfterEnv: ['<rootDir>/jest.setup.js'],
  testEnvironment: 'jest-environment-jsdom',
  moduleNameMapper: {
    '^@/(.*)$': '<rootDir>/$1',
  },
  testPathIgnorePatterns: ['<rootDir>/.next/', '<rootDir>/node_modules/', '<rootDir>/e2e/'],
}

// Matches the extensions Jest's default testMatch would pick up, so a
// `.database.test.tsx` cannot fall through to the parallel project and quietly
// reintroduce the collisions this split exists to remove.
const DATABASE_TESTS = '\\.database\\.test\\.[jt]sx?$'

/**
 * Two projects, because the database tests share one Postgres and must not run
 * beside each other.
 *
 * Several assert against whole tables on purpose — `seatAssignmentCoverage`
 * proves the invariant #137 relied on holds for data the test did not create —
 * so a fixture another file is holding open gets counted and the run fails on
 * work that is not its own (#155). Running them one file at a time removes the
 * overlap without weakening a single assertion.
 *
 * `npm run test:database` passes `--runInBand`, which is what actually
 * serialises them; splitting the projects is what lets it apply to those files
 * alone. It costs about 3s on those 9 files, and around 9s on the suite as a
 * whole once the two phases no longer interleave — roughly 21s to 31s. Worth
 * it for a result that does not depend on which files happen to overlap.
 *
 * createJestConfig is called this way to ensure next/jest can load the Next.js
 * config, which is async.
 */
module.exports = async () => ({
  projects: [
    await createJestConfig({
      ...customJestConfig,
      displayName: 'unit',
      testPathIgnorePatterns: [...customJestConfig.testPathIgnorePatterns, DATABASE_TESTS],
    })(),
    await createJestConfig({
      ...customJestConfig,
      displayName: 'database',
      testMatch: ['**/*.database.test.?(ts|tsx|js|jsx)'],
      // Refuses the run rather than letting it interfere quietly (#215).
      globalSetup: '<rootDir>/jest.database-setup.js',
    })(),
  ],
})
