100	    const flight = flights[activeLegIndex];
101	    const activeLegTabRef = useRef<HTMLButtonElement | null>(null);
102	    // Only an arrow key should pull focus onto the tab; clicking a tab or being
103	    // sent to a leg by validation must leave focus where the user put it.
104	    const legTabFocusPendingRef = useRef(false);
105	
106	    /** Arrow/Home/End move between legs, as the tab pattern expects. */
107	    const handleLegTabKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
108	        const lastIndex = flights.length - 1;
109	        let nextIndex: number | null = null;
110	        if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
111	            nextIndex = activeLegIndex === lastIndex ? 0 : activeLegIndex + 1;
112	        } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
113	            nextIndex = activeLegIndex === 0 ? lastIndex : activeLegIndex - 1;
114	        } else if (event.key === 'Home') {
115	            nextIndex = 0;
116	        } else if (event.key === 'End') {
117	            nextIndex = lastIndex;
118	        }
119	        if (nextIndex === null) return;
120	        event.preventDefault();
121	        legTabFocusPendingRef.current = true;
122	        setActiveLegIndex(nextIndex);
123	    };
124	
125	    useEffect(() => {
126	        if (!legTabFocusPendingRef.current) return;
127	        legTabFocusPendingRef.current = false;
128	        activeLegTabRef.current?.focus();
