132	        PREMIUM_ECONOMY: flight.premiumEconomyRows ?? 4,
133	        BUSINESS: flight.businessRows ?? 3,
134	        FIRST: flight.firstClassRows ?? 3
135	    };
136	    const availableCabins = (Object.keys(CABIN_FARE_PERCENT) as PassengerFormState['cabinClass'][])
137	        .filter(cabin => cabinRowCounts[cabin] > 0);
138	    // The cabin the customer shopped, when this leg operates it. Falling back
139	    // rather than failing: a leg without that cabin still has to be bookable.
140	    const defaultCabin = searchedCabin && availableCabins.includes(searchedCabin)
141	        ? searchedCabin
142	        : availableCabins[0];
143	
