            { flightId: inbound.id, seatNumber: '6A' },
        ]);

        const left = await prisma.seatHold.findMany({ where: { holderKey: holder } });
        expect(left).toHaveLength(1);
        expect(left[0].flightId).toBe(inbound.id);
    });
