/** How long a customer gets to finish choosing before the seat is offered on. */
export const HOLD_MINUTES = 10;

export interface SeatClaim {
    flightId: number;
    seatNumber: string;
    /** A server-derived key identifying one user's single checkout. */
    holderKey: string;
