    expect(adaBack).toHaveTextContent('Ada Lovelace');
    expect(adaBack).toHaveTextContent('Seat 11A');
    expect(graceBack).toHaveTextContent('Grace Hopper');
    expect(graceBack).toHaveTextContent('Seat 11B');
});

