.search-degraded button {
  height: auto;
  min-height: 44px;
  width: auto;
  padding: 10px 20px;
  background: #4a3d14;
  background-image: none;
  border: 1px solid rgba(251, 191, 36, 0.6);
  color: #fde68a;
  box-shadow: none;
}

/* This app sets no focus style of its own, so the control added here brings
   its own rather than inheriting a suppressed browser default (#80). */
.search-degraded button:focus-visible {
  outline: 3px solid #fbbf24;
  outline-offset: 2px;
}

