   it replaced rather than as a call to action. */
.guide-back {
  height: auto;
  width: auto;
  padding: 0;
  background: none;
  background-image: none;
  border: 0;
  box-shadow: none;
  color: inherit;
  font: inherit;
  font-weight: bold;
  text-decoration: underline;
  cursor: pointer;
}

